query siteWifiRadioProfileBySite ( $accountId:ID! $siteRefInput:SiteRefInput!) {
	site ( accountId:$accountId ) {
		wifiRadioProfileBySite ( input:$siteRefInput  )  {
			id
			site {
				id
				name
			}
			band24 {
				band
				standard
				channelWidth
				dfsEnabled
				channel
			}
			band5 {
				band
				standard
				channelWidth
				dfsEnabled
				channel
			}
		}
	}	
}
